"""Renders docs/MODEL_CARDS.md from the exported artifacts (numbers are copied by code, never by hand).

Usage: python scripts/build_model_cards.py
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ART = ROOT / "backend" / "app" / "ml" / "artifacts"
m1 = json.loads((ART / "model1" / "model1_card.json").read_text(encoding="utf-8"))
m2 = json.loads((ART / "model2" / "model2_card.json").read_text(encoding="utf-8"))
SYS = {"brakes": "Brakes", "electrical": "Electrical", "engine_emissions": "Engine-related"}
f = lambda x, n=3: f"{x:.{n}f}"
out = ["# Model cards (generated from the exported artifacts)", "", "Generated by `scripts/build_model_cards.py`. Every number below is read from `backend/app/ml/artifacts/`.", ""]

# ------------------------------------------------------------------ Model 1
v = m1["held_out_validation_uncalibrated"]
c = m1["calibration"]
out += [f"## {m1['name']} (v{m1['version']}, trained {m1['trained_at']})", "",
        f"* **Algorithm:** {m1['algorithm']}.",
        f"* **Training data:** {m1['training_data']['rows']:,} cleaned used-car listings " + "(" + ", ".join(f"{k}: {n:,}" for k, n in m1["training_data"]["datasets"].items()) + f"); {m1['training_data']['units']}.",
        f"* **Held-out validation of the learned model (training markets, uncalibrated, {v['n_test']:,} vehicles):** R2 = {f(v['R2'])}, RMSE = {v['RMSE_km']:,.0f} km, MAE = {v['MAE_km']:,.0f} km; the raw 10-90% quantile range covers {v['raw_80pct_interval_coverage_heldout'] * 100:.1f}% of held-out vehicles (nominal 80%).",
        f"* **Calibration to Israel:** {c['source']}. Families fitted: {', '.join(c['families'])}; supported age {c['supported_age']} years (above it the official yearly rate replaces the flat learned curve). Registry sample used: {c['registry_sample_rows']:,} real vehicles.",
        f"* **Check on CBS Table 8 joint cells never used in the fit:** mean absolute error {c['joint_cell_mean_abs_pct_error']:.1f}% over {len(c['held_out_joint_cells'])} cells.", "",
        "| Age band | CBS 2022 (thousand km/yr) | Model implied on the Israeli registry sample |", "|---|---|---|"]
for k, mm in c["marginals"].items():
    if k.startswith("age:"):
        out.append(f"| {k[4:]} | {mm['cbs_2022']} | {f(mm['model_thousand_km_per_year'], 1) if mm['model_thousand_km_per_year'] is not None else 'no vehicle in sample (official rate used)'} |")
out += ["", "| Ownership | CBS 2022 | Model implied |", "|---|---|---|"]
for k, mm in c["marginals"].items():
    if k.startswith("own:"):
        out.append(f"| {k[4:]} | {mm['cbs_2022']} | {f(mm['model_thousand_km_per_year'], 1) if mm['model_thousand_km_per_year'] is not None else '-'} |")
out += ["", "**Interval:** " + m1["interval"] + ".", "", "**Limitations**", ""] + [f"* {x}" for x in m1["limitations"]] + [""]

# ------------------------------------------------------------------ Model 2
out += [f"## {m2['name']} (v{m2['version']}, trained {m2['trained_at']})", "", f"* **Target:** {m2['target']}.",
        f"* **Training data (primary):** {m2['training_data']['primary']}: {m2['training_data']['uk']['pairs']:,} pairs of {m2['training_data']['uk']['vehicles']:,} vehicles. **Validation:** {m2['training_data']['validation']} ({m2['training_data']['nl']['pairs']:,} pairs).",
        "* **Variants:** " + "; ".join(f"`{k}` = {', '.join(cols)}" for k, cols in m2["variants"].items()) + ".",
        f"* **Mileage estimated by Model 1 is not a feature:** {m2['training_data']['mileage_estimated_by_model1']}.",
        f"* **Coverage:** fuels {', '.join(m2['coverage']['fuels'])}; age at the last inspection {m2['coverage']['age_years_at_last_inspection'][0]}-{m2['coverage']['age_years_at_last_inspection'][1]} years; {m2['coverage']['makes']}.",
        f"* **Development split (UK):** train {m2['uk_development_split']['train']:,} / validation {m2['uk_development_split']['validation']:,} / test {m2['uk_development_split']['test']:,} pairs; test pairs are later in time and from vehicles never seen in training.", "",
        "### UK test set (unseen vehicles, later dates)", "", "| System | Variant | ROC-AUC | PR-AUC (prevalence) | Capture in top 20% | Precision | Recall | F1 | F1 if every vehicle is flagged | ECE |", "|---|---|---|---|---|---|---|---|---|---|"]
for r in m2["uk_test_metrics"]:
    prev = r["prevalence"]
    out.append(f"| {SYS[r['system']]} | {r['variant']} | {f(r['ROC-AUC'])} | {f(r['PR-AUC'])} ({f(prev)}) | {f(r['capture_top20'])} | {f(r['Precision'])} | {f(r['Recall'])} | {f(r['F1'])} | {f(2 * prev / (1 + prev))} | {f(r['ECE'], 4)} |")
out += ["", "### Logistic Regression benchmark (same test set)", "", "| System | Variant | ROC-AUC (XGBoost) | ROC-AUC (Logistic Regression) |", "|---|---|---|---|"]
for r in m2["uk_logistic_regression_benchmark"]:
    x = next(q for q in m2["uk_test_metrics"] if q["system"] == r["system"] and q["variant"] == r["variant"])
    out.append(f"| {SYS[r['system']]} | {r['variant']} | {f(x['ROC-AUC'])} | {f(r['ROC-AUC'])} |")
out += ["", "### Independent validation on the Dutch RDW inspections (models trained on UK only; targets in 2026)", "",
        "| System | Variant | ROC-AUC UK-trained | ROC-AUC trained in the Netherlands | Capture top 20% | Observed rate | Mean predicted | ECE raw | ECE after base-rate correction |", "|---|---|---|---|---|---|---|---|---|"]
for r in m2["netherlands_external_validation"]:
    ref = next(q for q in m2["netherlands_in_country_reference"] if q["system"] == r["system"] and q["variant"] == r["variant"])
    out.append(f"| {SYS[r['system']]} | {r['variant']} | {f(r['ROC-AUC'])} | {f(ref['ROC-AUC'])} | {f(r['capture_top20'])} | {f(r['prevalence'])} | {f(r['mean_predicted'])} | {f(r['ECE'], 4)} | {f(r['ECE_after_base_rate_correction'], 4)} |")
out += ["", "### Cross-fitted scores on all UK pairs (basis of the same-age bands)", "", "| System | Variant | ROC-AUC | ECE | Share of vehicles in the 'higher' band | Share of defects they hold | Defect rate in that band |", "|---|---|---|---|---|---|---|"]
for r in m2["uk_cross_fitted"]:
    out.append(f"| {SYS[r['system']]} | {r['variant']} | {f(r['ROC-AUC'])} | {f(r['ECE'], 4)} | {f(r['share_flagged_higher_band'])} | {f(r['share_of_defects_in_higher_band'])} | {f(r['defect_rate_in_higher_band'])} |")
out += ["", "**Bands:** " + "; ".join(f"{k}: {v}" for k, v in m2["bands"].items()) + ".", "", "**Limitations**", ""] + [f"* {x}" for x in m2["limitations"]] + [""]
(ROOT / "docs").mkdir(exist_ok=True)
(ROOT / "docs" / "MODEL_CARDS.md").write_text("\n".join(out), encoding="utf-8")
print("written docs/MODEL_CARDS.md,", len(out), "lines")
